pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 _sameVal) internal {
        uint256 beforeMin;
        try c.MinSum() returns (uint256 __r) { beforeMin = __r; } catch { return; }
        try c.SetMinSum(beforeMin) {} catch { return; }
        uint256 afterMin;
        try c.MinSum() returns (uint256 __r) { afterMin = __r; } catch { return; }
        assertTrue(afterMin == beforeMin);
    }

    function testFuzz_run(uint256 _sameVal) public {
        _run(_sameVal);
    }

    receive() external payable {}
}
